# .claude/hooks/log-tools.sh
#!/bin/bash
TOOL="$CLAUDE_TOOL_NAME"
INPUT=$(echo "$CLAUDE_TOOL_INPUT" | jq -c '.')
echo "[$(date +%H:%M:%S)] Tool: $TOOL | Input: $INPUT" >> .claude/tool-log.txt
# Exit 0 = allow the tool to proceed
exit 0

# .claude/settings.json
{
  "hooks": {
    "PreToolUse": [{
      "matcher": "",
      "hooks": [{"type": "command", "command": "bash .claude/hooks/log-tools.sh"}]
    }]
  }
}

# Auto-format TypeScript files after Claude writes them
# .claude/hooks/format-on-write.sh
#!/bin/bash
FILE=$(echo "$CLAUDE_TOOL_INPUT" | jq -r '.file_path // empty')
if [[ "$FILE" == *.ts || "$FILE" == *.tsx ]]; then
  npx prettier --write "$FILE" 2>/dev/null
  echo "Formatted: $FILE"
fi
exit 0

# .claude/settings.json
{
  "hooks": {
    "PostToolUse": [{
      "matcher": "Write",
      "hooks": [{"type": "command", "command": "bash .claude/hooks/format-on-write.sh"}]
    }]
  }
}

