# .claude/hooks/notify-done.sh
#!/bin/bash
# Send macOS notification when Claude finishes
osascript -e 'display notification "Claude has finished" with title "Claude Code" sound name "Glass"'

# Or send a Slack message:
curl -s -X POST "$SLACK_WEBHOOK_URL" \
  -H 'Content-Type: application/json' \
  -d '{"text":"Claude Code task completed in '"$PWD"'"}'

# .claude/settings.json
{
  "hooks": {
    "Stop": [{
      "hooks": [{"type": "command", "command": "bash .claude/hooks/notify-done.sh"}]
    }]
  }
}

# .claude/settings.ci.json (used in CI environments)
{
  "hooks": {
    "PostToolUse": [{
      "matcher": "Write",
      "hooks": [{
        "type": "command",
        "command": "bash .claude/hooks/ci-quality-gate.sh"
      }]
    }]
  }
}

# .claude/hooks/ci-quality-gate.sh
#!/bin/bash
FILE=$(echo "$CLAUDE_TOOL_INPUT" | jq -r '.file_path // empty')
[[ -z "$FILE" ]] && exit 0
[[ "$FILE" != *.ts && "$FILE" != *.tsx ]] && exit 0

# Run type check on the specific file
if ! npx tsc --noEmit --allowJs "$FILE" 2>&1; then
  echo "Type check failed for $FILE. Fix type errors before proceeding." >&2
  exit 2
fi
